/**
 * SPEC-059: la sección «Guión» sin guión deja de ofrecer «Generar guión». El
 * botón de la cabecera y el CTA del empty state duplicaban el paso 2 del banner
 * de onboarding, que es el único primary del contenido de la página. El CTA del
 * empty state reaparece SOLO como respaldo cuando el banner no está visible
 * (oculto por el usuario o grabación en curso) y los prerrequisitos se cumplen:
 * entonces es la única superficie de generación que queda.
 * Generated by QA Dev agent.
 *
 * Frontera de mocking: window.api (installMockApi). Los escenarios con banner
 * se montan por la página real (InterviewDetailPage), que compone banner +
 * secciones dentro del puente; el escenario «grabación en curso» monta la
 * sección directamente con `capturing`, porque llevar la página hasta una
 * grabación viva es ruido para lo que verifica el AC (la otra mitad del mismo
 * criterio de lib/onboardingStep).
 */
import { act, render, screen, waitFor, within, type RenderResult } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { MemoryRouter, Route, Routes } from 'react-router-dom'
import { Toaster } from '@/components/ui/sonner'
import { TooltipProvider } from '@/components/ui/tooltip'
import { ScriptSection } from '@/components/interviews/ScriptSection'
import { InterviewDetailPage } from '@/pages/InterviewDetailPage'
import type { Company, Interview } from '@/types/domain'
import { installMockApi, type MockApiHandle } from '../../helpers/mockApi'

let mockApi: MockApiHandle

const COMPANY: Company = {
  id: 'c-1',
  name: 'Acme Corp',
  website: null,
  linkedinUrl: null,
  createdAt: '2026-07-02T12:00:00.000Z',
  updatedAt: '2026-07-02T12:00:00.000Z'
}

function interview(overrides: Partial<Interview> = {}): Interview {
  return {
    id: 'i-1',
    discoveryId: 'd-1',
    companyId: 'c-1',
    contactIds: [],
    interviewGroupId: null,
    templateId: 'tpl-1',
    title: 'Discovery con Acme',
    status: 'draft',
    scriptMarkdown: null,
    objectives: [],
    wavPath: null,
    transcriptPath: null,
    createdAt: '2026-07-04T10:00:00.000Z',
    updatedAt: '2026-07-04T10:00:00.000Z',
    ...overrides
  }
}

function setInterview(value: Interview): void {
  vi.mocked(mockApi.api.db.getInterview).mockResolvedValue({ ok: true, data: value })
}

function setHasKey(hasAnthropicKey: boolean): void {
  vi.mocked(mockApi.api.llm.getStatus).mockResolvedValue({
    ok: true,
    data: { hasAnthropicKey }
  })
}

function renderDetail(): RenderResult {
  return render(
    <TooltipProvider>
      <MemoryRouter initialEntries={['/discoveries/d-1/companies/c-1/interviews/i-1']}>
        <Routes>
          <Route
            path="/discoveries/:discoveryId/companies/:companyId/interviews/:interviewId"
            element={<InterviewDetailPage />}
          />
        </Routes>
      </MemoryRouter>
      <Toaster />
    </TooltipProvider>
  )
}

/** Sección Guión suelta: única forma limpia de fijar `capturing`. */
function renderSection(value: Interview, capturing: boolean): RenderResult {
  return render(
    <TooltipProvider>
      <MemoryRouter>
        <ScriptSection interview={value} onInterviewUpdated={vi.fn()} capturing={capturing} />
      </MemoryRouter>
      <Toaster />
    </TooltipProvider>
  )
}

/** Botones «Generar guión» que NO son el espejado del banner. */
function sectionGenerateButtons(): HTMLElement[] {
  return screen
    .queryAllByRole('button', { name: 'Generar guión' })
    .filter((button) => button.dataset.testid !== 'onboarding-step-action')
}

/**
 * Espera a que la sección Guión esté montada Y con la clave resuelta. El
 * heading es asíncrono (Skeleton de NoteScriptSections mientras resuelve
 * getNoteByInterview) y, entre el montaje y la resolución de la clave, el
 * registro del puente deja el botón del banner deshabilitado: esperar «heading
 * y luego habilitado» garantiza que un assert de AUSENCIA de CTA no sea vacuo
 * por llegar antes de que `canGenerate` pueda ser cierto.
 */
async function waitForScriptSectionReady(): Promise<HTMLElement> {
  const banner = await screen.findByTestId('interview-onboarding-banner')
  await screen.findByRole('heading', { name: 'Guión' })
  await waitFor(() => expect(within(banner).getByTestId('onboarding-step-action')).toBeEnabled())
  return banner
}

/** Resultado de `llm.getStatus` sin importar el tipo del contrato. */
type StatusResult = Awaited<ReturnType<MockApiHandle['api']['llm']['getStatus']>>

beforeEach(() => {
  vi.clearAllMocks()
  mockApi = installMockApi()
  vi.mocked(mockApi.api.db.getCompany).mockResolvedValue({ ok: true, data: COMPANY })
  setInterview(interview())
  setHasKey(true)
})

describe('ScriptSection clean state (SPEC-059)', () => {
  describe('with the onboarding banner visible', () => {
    // SPEC-059 · AC-03
    it('renders the Guión heading without a "Generar guión" button in the header', async () => {
      renderDetail()

      const banner = await waitForScriptSectionReady()
      const heading = screen.getByRole('heading', { name: 'Guión' })
      const header = heading.parentElement
      if (header === null) {
        throw new Error('El heading «Guión» debe vivir en la fila de cabecera de la sección')
      }
      expect(within(header).queryByRole('button')).not.toBeInTheDocument()
      // El banner sigue ofreciendo la acción (paso 2): la cabecera de la
      // sección es la que se queda sin botón
      expect(banner).toHaveAttribute('data-step', '2')
      expect(within(banner).getByTestId('onboarding-step-action')).toHaveTextContent(
        'Generar guión'
      )
    })

    // SPEC-059 · AC-04: excepción justificada al design system — la acción no
    // desaparece de la pantalla, vive en el banner inmediatamente encima
    it('renders the "Aún no hay guión" empty state without any action button', async () => {
      renderDetail()

      await waitForScriptSectionReady()
      expect(screen.getByText('Aún no hay guión')).toBeInTheDocument()
      // Con los prerrequisitos cumplidos (la espera lo garantiza) el CTA
      // seguiría existiendo de no ser por esta spec
      expect(sectionGenerateButtons()).toHaveLength(0)
    })
  })

  describe('with the onboarding banner hidden by the user', () => {
    const HIDDEN = interview({ onboardingHiddenAt: '2026-07-29T09:00:00.000Z' })

    // SPEC-059 · AC-13: sin banner que la ofrezca, el CTA de respaldo vuelve
    it('brings the empty state CTA back and generates from it when the prerequisites are met', async () => {
      const user = userEvent.setup()
      setInterview(HIDDEN)
      vi.mocked(mockApi.api.llm.generateScript).mockResolvedValue({
        ok: true,
        data: interview({
          ...HIDDEN,
          scriptMarkdown: '# Bloque 1\n\nPregunta adaptada a Acme',
          status: 'prepared'
        })
      })
      renderDetail()

      expect(screen.queryByTestId('interview-onboarding-banner')).not.toBeInTheDocument()
      await waitFor(() => expect(sectionGenerateButtons()).toHaveLength(1))
      const cta = sectionGenerateButtons()[0]
      expect(cta).toBeEnabled()

      await user.click(cta)
      expect(vi.mocked(mockApi.api.llm.generateScript)).toHaveBeenCalledWith('i-1')
      expect(await screen.findByText('Pregunta adaptada a Acme')).toBeInTheDocument()
    })

    // SPEC-059 · AC-14: sin plantilla no hay CTA (comportamiento del empty
    // state anterior a la spec, sin cambios)
    it('does not show the CTA when the template is missing', async () => {
      // getStatus diferido: sin banner ni CTA no hay nada positivo que
      // observar, así que la resolución de la clave se controla a mano para
      // que el assert de ausencia no sea vacuo.
      let resolveStatus!: (value: StatusResult) => void
      vi.mocked(mockApi.api.llm.getStatus).mockReturnValue(
        new Promise<StatusResult>((resolve) => {
          resolveStatus = resolve
        })
      )
      setInterview(interview({ ...HIDDEN, templateId: null }))
      renderDetail()

      expect(await screen.findByText('Aún no hay guión')).toBeInTheDocument()
      await act(async () => {
        resolveStatus({ ok: true, data: { hasAnthropicKey: true } })
      })
      expect(sectionGenerateButtons()).toHaveLength(0)
    })

    // SPEC-059 · AC-14 (segundo prerrequisito): sin clave tampoco hay CTA, y
    // el Alert accionable de la sección sigue en su sitio (AC-05)
    it('does not show the CTA when the Anthropic key is missing but keeps the key alert', async () => {
      setHasKey(false)
      setInterview(HIDDEN)
      renderDetail()

      const alert = await screen.findByRole('alert')
      expect(alert).toHaveTextContent(
        'Configura tu clave de Anthropic en Ajustes para generar el guión'
      )
      expect(sectionGenerateButtons()).toHaveLength(0)
    })
  })

  describe('with a recording in progress', () => {
    // SPEC-059 · AC-13 (la otra mitad del criterio de banner visible): durante
    // la grabación el banner tampoco está, así que el CTA de respaldo vuelve
    it('brings the empty state CTA back while capturing', async () => {
      renderSection(interview(), true)

      expect(await screen.findByText('Aún no hay guión')).toBeInTheDocument()
      await waitFor(() => expect(sectionGenerateButtons()).toHaveLength(1))
      expect(sectionGenerateButtons()[0]).toBeEnabled()
    })
  })
})
